 "content": "def transform(grid):
    """Connect equal-colored diagonal markers, preserving existing markers."""
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    points = {}
    for r in range(h):
        for c in range(w):
            if grid[r][c] not in (1, 6):
                continue
            color = grid[r][c]
            for dr, dc in ((1, 1), (1, -1)):
                points.setdefault((color, dr, dc, r - c if dc == 1 else r + c), []).append((r, c))
    for (color, dr, dc, _), pts in points.items():
        if len(pts) < 2:
            continue
        pts.sort(key=lambda p: p[0])
        for (r1, c1), (r2, c2) in zip(pts, pts[1:]):
            # Fill only when the two markers share a 45-degree diagonal.
            if abs(r2-r1) != abs(c2-c1):
                continue
            step_c = 1 if c2 > c1 else -1
            for k in range(1, r2-r1):
                rr, cc = r1+k, c1+k*step_c
                if out[rr][cc] not in (1, 6):
                    out[rr][cc] = color
    return out
