 "content": "def transform(grid):
    """Connect diagonal pairs of 1s; 6s on that connector project across it."""
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    ones = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 1]
    connectors = []
    for i, (r1, c1) in enumerate(ones):
        for r2, c2 in ones[i + 1:]:
            if abs(r2-r1) == abs(c2-c1):
                dr = 1 if r2 > r1 else -1
                dc = 1 if c2 > c1 else -1
                connectors.append((r1, c1, r2, c2, dr, dc))
                for k in range(1, abs(r2-r1)):
                    rr, cc = r1 + k*dr, c1 + k*dc
                    if out[rr][cc] == 4:
                        out[rr][cc] = 1
    for r1, c1, r2, c2, dr, dc in connectors:
        for k in range(abs(r2-r1)+1):
            rr, cc = r1 + k*dr, c1 + k*dc
            if grid[rr][cc] != 6:
                continue
            # A 6 lying on the 1-connector draws its other diagonal to both edges.
            pr, pc = (1, -1) if dr == dc else (1, 1)
            rr2, cc2 = rr, cc
            while 0 <= rr2-pr < h and 0 <= cc2-pc < w:
                rr2 -= pr; cc2 -= pc
            while 0 <= rr2 < h and 0 <= cc2 < w:
                if out[rr2][cc2] == 4:
                    out[rr2][cc2] = 6
                rr2 += pr; cc2 += pc
    return out
