    """Draw diagonal 1-to-1 connectors and perpendicular 6 projections.

    Every original 6 projects on both diagonal orientations. A 6 lying on a
    connector also takes part in the continuation of that connector's line.
    """
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    ones = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 1]
    connectors = []
    for i, (r1, c1) in enumerate(ones):
        for r2, c2 in ones[i+1:]:
            if abs(r2-r1) == abs(c2-c1):
                dr = 1 if r2 > r1 else -1
                dc = 1 if c2 > c1 else -1
                cells = [(r1+k*dr, c1+k*dc) for k in range(abs(r2-r1)+1)]
                connectors.append((dr, dc, cells))
                for rr, cc in cells[1:-1]:
                    if grid[rr][cc] not in (1, 6):
                        out[rr][cc] = 1

    # A 6 in the grid creates a full 45-degree line of 6s, regardless of
    # whether it lies on a connector; connector crossings do not change it.
    directions = ((1, 1), (1, -1))
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 6:
                continue
            for dr, dc in directions:
                sr, sc = r, c
                while 0 <= sr-dr < h and 0 <= sc-dc < w:
                    sr -= dr
                    sc -= dc
                while 0 <= sr < h and 0 <= sc < w:
                    if grid[sr][sc] not in (1, 6):
                        out[sr][sc] = 6
                    sr += dr
                    sc += dc
    return out
